window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c8439d8bd060d85f"]={"versions": [{"id": "FIG-c8439d8bd060d85f", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung von Ports und Schnittstellen im Rahmen der AUTOSAR Abstract Platform Specification (TPS AbstractPlatformSpecification). Dargestellt ist die strukturelle Modellierung von Ports (<code>PortPrototype</code>) an Software-Komponententypen (<code>SwComponentType</code>) sowie deren Typisierung über <code>PortInterface</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>SwComponentType</code> (Stereotypen/Eigenschaften: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Aggregiert über eine Komposition <code>+port</code> mit Multiplizität <code>0..*</code> Instanzen von <code>PortPrototype</code>. Die Komposition ist mit <code>«atpVariation,atpSplitable»</code> annotiert.\n</li><li><code>PortPrototype</code> (Eigenschaften: <code>AtpBlueprintable</code>, <code>AtpPrototype</code>): Abstrakte Basisklasse für Port-Prototypen.\n</li><li><code>AbstractProvidedPortPrototype</code> und <code>AbstractRequiredPortPrototype</code>: Generalisieren <code>PortPrototype</code>.\n</li><li><code>PPortPrototype</code>: Spezialisiert <code>AbstractProvidedPortPrototype</code>. Besitzt eine gerichtet referenzierende Assoziation <code>«isOfType»</code> mit Rollenbezeichnung <code>+providedInterface</code>, Multiplizität <code>1</code> und Eigenschaft <code>{redefines atpType}</code> auf <code>PortInterface</code>.\n</li><li><code>RPortPrototype</code>: Spezialisiert <code>AbstractRequiredPortPrototype</code>. Besitzt eine gerichtet referenzierende Assoziation <code>«isOfType»</code> mit Rollenbezeichnung <code>+requiredInterface</code>, Multiplizität <code>1</code> und Eigenschaft <code>{redefines atpType}</code> auf <code>PortInterface</code>.\n</li><li><code>PortInterface</code> (Eigenschaften: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Repräsentiert die Schnittstellendefinition.\n</li><li><code>CompositeInterface</code>: Spezialisiert <code>PortInterface</code> über Vererbung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm (Metamodell-Ausschnitt) ohne dynamische Sequenzabläufe, Nachrichtenflüsse oder Zustandsübergänge zur Laufzeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Bindungszeit für Variabilität: An der Komposition <code>+port</code> ist über den Stereotyp <code>«atpVariation»</code> der Tag <code>vh.latestBindingTime = preCompileTime</code> festgelegt.\n</li><li>Splitbarkeit: Das Attribut <code>port</code> ist <code>«atpSplitable»</code>.\n</li><li>Typisierungsanforderung: Jeder <code>PPortPrototype</code> und jeder <code>RPortPrototype</code> muss zwingend genau ein <code>PortInterface</code> referenzieren (Kardinalität <code>1</code>), welches das geerbte Metamodell-Attribut <code>atpType</code> redefiniert.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b9b8d99d003d2f53", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung von Ports und Schnittstellen im Rahmen der AUTOSAR Abstract Platform Specification (TPS AbstractPlatformSpecification). Dargestellt ist die strukturelle Modellierung von Ports (<code>PortPrototype</code>) an Software-Komponententypen (<code>SwComponentType</code>) sowie deren Typisierung über <code>PortInterface</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>SwComponentType</code> (Stereotypen/Eigenschaften: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Aggregiert über eine Komposition <code>+port</code> mit Multiplizität <code>0..*</code> Instanzen von <code>PortPrototype</code>. Die Komposition ist mit <code>«atpVariation,atpSplitable»</code> annotiert.\n</li><li><code>PortPrototype</code> (Eigenschaften: <code>AtpBlueprintable</code>, <code>AtpPrototype</code>): Abstrakte Basisklasse für Port-Prototypen.\n</li><li><code>AbstractProvidedPortPrototype</code> und <code>AbstractRequiredPortPrototype</code>: Generalisieren <code>PortPrototype</code>.\n</li><li><code>PPortPrototype</code>: Spezialisiert <code>AbstractProvidedPortPrototype</code>. Besitzt eine gerichtet referenzierende Assoziation <code>«isOfType»</code> mit Rollenbezeichnung <code>+providedInterface</code>, Multiplizität <code>0..1</code> und Eigenschaft <code>{redefines atpType}</code> auf <code>PortInterface</code>.\n</li><li><code>RPortPrototype</code>: Spezialisiert <code>AbstractRequiredPortPrototype</code>. Besitzt eine gerichtet referenzierende Assoziation <code>«isOfType»</code> mit Rollenbezeichnung <code>+requiredInterface</code>, Multiplizität <code>0..1</code> und Eigenschaft <code>{redefines atpType}</code> auf <code>PortInterface</code>.\n</li><li><code>PortInterface</code> (Eigenschaften: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Repräsentiert die Schnittstellendefinition.\n</li><li><code>CompositeInterface</code>: Spezialisiert <code>PortInterface</code> über Vererbung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm (Metamodell-Ausschnitt) ohne dynamische Sequenzabläufe, Nachrichtenflüsse oder Zustandsübergänge zur Laufzeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Bindungszeit für Variabilität: An der Komposition <code>+port</code> ist über den Stereotyp <code>«atpVariation»</code> der Tag <code>vh.latestBindingTime = preCompileTime</code> festgelegt.\n</li><li>Splitbarkeit: Das Attribut <code>port</code> ist <code>«atpSplitable»</code>.\n</li><li>Typisierungsanforderung: Die Zuweisung eines <code>PortInterface</code> an <code>PPortPrototype</code> (<code>+providedInterface</code>) bzw. <code>RPortPrototype</code> (<code>+requiredInterface</code>) ist optional (Kardinalität jeweils <code>0..1</code>). Bei Vorhandensein redefiniert die Assoziation das Metamodell-Attribut <code>atpType</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-871fe1b056fea5ac", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung von Ports und Schnittstellen im Rahmen der AUTOSAR Abstract Platform Specification (TPS AbstractPlatformSpecification). Dargestellt ist die strukturelle Modellierung von Ports (<code>PortPrototype</code>) an Software-Komponententypen (<code>SwComponentType</code>) sowie deren Typisierung über <code>PortInterface</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>SwComponentType</code> (Stereotypen/Eigenschaften: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Aggregiert über eine Komposition <code>+port</code> mit Multiplizität <code>0..*</code> Instanzen von <code>PortPrototype</code>. Die Komposition ist mit <code>«atpVariation,atpSplitable»</code> annotiert.\n</li><li><code>PortPrototype</code> (Eigenschaften: <code>AtpBlueprintable</code>, <code>AtpPrototype</code>): Abstrakte Basisklasse für Port-Prototypen.\n</li><li><code>AbstractProvidedPortPrototype</code> und <code>AbstractRequiredPortPrototype</code>: Generalisieren <code>PortPrototype</code>.\n</li><li><code>PPortPrototype</code>: Spezialisiert <code>AbstractProvidedPortPrototype</code>. Besitzt eine gerichtet referenzierende Assoziation <code>«isOfType»</code> mit Rollenbezeichnung <code>+providedInterface</code>, Multiplizität <code>0..1</code> und Eigenschaft <code>{redefines atpType}</code> auf <code>PortInterface</code>.\n</li><li><code>RPortPrototype</code>: Spezialisiert <code>AbstractRequiredPortPrototype</code>. Besitzt eine gerichtet referenzierende Assoziation <code>«isOfType»</code> mit Rollenbezeichnung <code>+requiredInterface</code>, Multiplizität <code>0..1</code> und Eigenschaft <code>{redefines atpType}</code> auf <code>PortInterface</code>.\n</li><li><code>PortInterface</code> (Eigenschaften: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Repräsentiert die Schnittstellendefinition.\n</li><li><code>ApplicationInterface</code>: Spezialisiert <code>PortInterface</code> über Vererbung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm (Metamodell-Ausschnitt) ohne dynamische Sequenzabläufe, Nachrichtenflüsse oder Zustandsübergänge zur Laufzeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Bindungszeit für Variabilität: An der Komposition <code>+port</code> ist über den Stereotyp <code>«atpVariation»</code> der Tag <code>vh.latestBindingTime = preCompileTime</code> festgelegt.\n</li><li>Splitbarkeit: Das Attribut <code>port</code> ist <code>«atpSplitable»</code>.\n</li><li>Typisierungsanforderung: Die Zuweisung eines <code>PortInterface</code> an <code>PPortPrototype</code> (<code>+providedInterface</code>) bzw. <code>RPortPrototype</code> (<code>+requiredInterface</code>) ist optional (Kardinalität jeweils <code>0..1</code>). Bei Vorhandensein redefiniert die Assoziation das Metamodell-Attribut <code>atpType</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c8439d8bd060d85f", "to": "FIG-b9b8d99d003d2f53", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Kardinalität an der Assoziation <code>PPortPrototype</code> -&gt; <code>PortInterface</code> (<code>+providedInterface</code>): von <code>1 {redefines atpType}</code> auf <code>0..1 {redefines atpType}</code> geändert.\n</li><li>Kardinalität an der Assoziation <code>RPortPrototype</code> -&gt; <code>PortInterface</code> (<code>+requiredInterface</code>): von <code>1 {redefines atpType}</code> auf <code>0..1 {redefines atpType}</code> geändert.\n</li></ul>"}, {"from": "FIG-b9b8d99d003d2f53", "to": "FIG-871fe1b056fea5ac", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Spezialisierung von <code>PortInterface</code>: <code>CompositeInterface</code> ersetzt durch <code>ApplicationInterface</code>.\n</li></ul>"}]};
